SELECT items.item_name, sales_detail.qty, sales_detail.total_sft, items.unit, sales_detail.mat_sale_price, sales_detail.amount, sales_detail.tax_amount, sales_detail.total_amount, ledger.lgID, ledger.contactnumber, ledger.contactaddress, ledger.city, ledger.state, ledger.GSTNo, sales_entry.outputsgst, sales_entry.outputcgst, sales_entry.outputigst, sales_entry.customer_id, sales_entry.sale_type, sales_entry.tax_type, sales_entry.discount, sales_entry.labour, sales_entry.final_bill, sales_entry.total_bill_sft, sales_entry.total_qty, sales_entry.SEID, sales_entry.sales_date, sales_entry.transport, sales_entry.driver_number, sales_entry.total_tax, sales_entry.total_bill
FROM (ledger INNER JOIN sales_entry ON ledger.lgID = sales_entry.customer_id) INNER JOIN (items INNER JOIN sales_detail ON items.item_id = sales_detail.item_id) ON sales_entry.SEID = sales_detail.SEID;

